-- DG FIT: recipes generated by the recipe builder and saved by their owner.
-- System client only (owner checked in services/dgfit/recipeService.ts).
CREATE TABLE IF NOT EXISTS public.dgfit_recipes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE,
  title text NOT NULL,
  kind text NOT NULL,
  recipe jsonb NOT NULL,
  request jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS dgfit_recipes_user_idx ON public.dgfit_recipes (user_id, created_at DESC);
